"""Build or check the addendum's generated files and the README chart (DECISIONS D-133).

``build_all`` computes every output in memory from the three pinned results:
``paper/addendum/generated/{numbers.tex, tables/*.tex, figures/*.pdf + .json, index.json}`` and
``docs/media/readme_extensions.{svg,json}``. ``write`` puts them on disk; ``check`` compares them
with the committed files byte for byte (``index.json`` apart from its git field). ``lint``
checks ``paper/addendum/addendum.tex``: every ``\\ax{key}`` is defined and no bare number
appears in the prose.
"""

from __future__ import annotations

import hashlib
import json
import re
from pathlib import Path
from typing import Any

from roboforge.addendum import figures, numbers, sources, tables
from roboforge.paper.lint import bare_numbers
from roboforge.paths import REPO_ROOT
from roboforge.provenance import git_revision

OUT = "paper/addendum/generated"
TEX = "paper/addendum/addendum.tex"
CHART = "docs/media/readme_extensions.svg"
CHART_DATA = "docs/media/readme_extensions.json"
INDEX_SCHEMA = "roboforge.addendum_assets/1"
PREFIX = "ax@"
# Identifiers the addendum may write with digits, beyond the paper's allowed tokens.
EXTRA_TOKENS = re.compile(r"^(?:X[123]|v1\.0\.0|v1\.1\.0|v1\.1|H2-c|Session-?\d{1,2})$")


def numbers_tex(n: numbers.Numbers) -> str:
    """``numbers.tex`` with the addendum's own macro prefix and its sources in the header."""
    lines = ["% Generated by scripts/addendum_assets.py (DECISIONS D-133). Do not edit.",
             "% Sources (path sha256):"]
    lines += [f"%   {s.path} {s.sha256}" for s in sources.SOURCES.values()]
    lines += [f"\\expandafter\\def\\csname {PREFIX}{k}\\endcsname{{{v}}}"
              for k, v in n.values.items()]
    return "\n".join(lines) + "\n"


def _header() -> str:
    lines = ["% Generated by scripts/addendum_assets.py (DECISIONS D-133). Do not edit.",
             "% Every cell is an \\ax{} macro of numbers.tex; sources:"]
    lines += [f"%   {s.path} {s.sha256}" for s in sources.SOURCES.values()]
    return "\n".join(lines) + "\n"


def _side(path: str, data: Any) -> bytes:
    return json.dumps({"figure": path, "plotted_values": data,
                       "sources": [{"path": s.path, "sha256": s.sha256}
                                   for s in sources.SOURCES.values()]},
                      indent=1, sort_keys=True).encode() + b"\n"


def build_all(root: Path = REPO_ROOT) -> dict[str, bytes]:
    """Every generated output as ``{relative path: bytes}``."""
    src = sources.load_all(root)
    n = numbers.build_numbers(src)
    files: dict[str, bytes] = {f"{OUT}/numbers.tex": numbers_tex(n).encode()}
    for name, fn in tables.TABLES.items():
        files[f"{OUT}/tables/{name}.tex"] = (_header() + fn()).encode()
    for name, fn in figures.FIGURES.items():
        rel = f"{OUT}/figures/{name}.pdf"
        fig, data = fn(src)
        files[rel] = figures.pdf_bytes(fig)
        files[rel.replace(".pdf", ".json")] = _side(rel, data)
    fig, data = figures.readme_chart(src)
    files[CHART] = figures.svg_bytes(fig)
    files[CHART_DATA] = _side(CHART, data)
    index = {
        "schema": INDEX_SCHEMA, "decision": "D-133",
        "generator": "scripts/addendum_assets.py (roboforge.addendum)",
        "sources": [{"path": s.path, "sha256": s.sha256, "label": s.label}
                    for s in sources.SOURCES.values()],
        "derived": numbers.DERIVED, "n_keys": len(n.values),
        "note": "Values copied from the pinned results at their tables' rounding; derived "
                "values are counts or plain arithmetic. runs/ is never read.",
        "git": git_revision(root),
        "outputs": [{"path": p, "sha256": hashlib.sha256(b).hexdigest()}
                    for p, b in sorted(files.items())],
    }
    files[f"{OUT}/index.json"] = (json.dumps(index, indent=1, sort_keys=True) + "\n").encode()
    return files


def _generated_on_disk(root: Path) -> set[str]:
    out = root / OUT
    found = {p.relative_to(root).as_posix() for p in out.rglob("*") if p.is_file()} \
        if out.exists() else set()
    return found | {p for p in (CHART, CHART_DATA) if (root / p).exists()}


def write(files: dict[str, bytes], root: Path = REPO_ROOT) -> list[str]:
    """Write every output and remove stale files under the generated directory."""
    for rel in sorted(_generated_on_disk(root) - set(files)):
        (root / rel).unlink()
    for rel, data in files.items():
        p = root / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
    return sorted(files)


def _index_without_git(data: bytes) -> Any:
    d = json.loads(data)
    d.pop("git", None)
    return d


def check(files: dict[str, bytes], root: Path = REPO_ROOT) -> list[str]:
    """Differences between a fresh build and the committed outputs (empty when equal)."""
    problems = []
    on_disk = _generated_on_disk(root)
    for rel in sorted(set(files) | on_disk):
        if rel not in files:
            problems.append(f"{rel}: on disk but not generated")
        elif rel not in on_disk:
            problems.append(f"{rel}: generated but missing on disk")
        elif rel.endswith("index.json"):
            if _index_without_git(files[rel]) != _index_without_git((root / rel).read_bytes()):
                problems.append(f"{rel}: differs (ignoring its git field)")
        elif (root / rel).read_bytes() != files[rel]:
            problems.append(f"{rel}: differs from a fresh build")
    return problems


def defined_keys(root: Path = REPO_ROOT) -> set[str]:
    """Keys defined in the committed addendum ``numbers.tex``."""
    txt = (root / OUT / "numbers.tex").read_text()
    return set(re.findall(r"\\csname " + re.escape(PREFIX) + r"([^\\]+)\\endcsname", txt))


def lint(root: Path = REPO_ROOT) -> list[str]:
    """Problems of ``addendum.tex``: undefined keys, bare numbers, placeholders."""
    p = root / TEX
    if not p.is_file():
        return [f"{TEX}: missing"]
    if not (root / OUT / "numbers.tex").is_file():
        return [f"{OUT}/numbers.tex missing: run make addendum-assets"]
    txt = p.read_text()
    problems = []
    keys = defined_keys(root)
    body = re.sub(r"(?<!\\)%.*", "", txt)
    for k in sorted(set(re.findall(r"\\ax\{([^}]*)\}", body)) - keys):
        problems.append(f"{TEX}: \\ax{{{k}}} is not defined in {OUT}/numbers.tex")
    prose = body.split("\\begin{document}", 1)[-1]
    prose = re.sub(r"\\ax\{[^}]*\}", " ", prose)
    for tok in bare_numbers(prose):
        if not EXTRA_TOKENS.match(tok):
            problems.append(f"{TEX}: bare number '{tok}' (use \\ax{{}} or an identifier)")
    if re.search(r"\bTBD\b|\bTODO\b|\bXXX\b|\?\?", body.split("\\begin{document}", 1)[-1]):
        problems.append(f"{TEX}: placeholder")
    return problems
